package br.com.sussmartcare.patientregistry.domain; import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="representative_relationships") public class RepresentativeRelationship { @Id private UUID id; @Column(nullable=false) private UUID patientId; @Column(nullable=false) private UUID representativeUserId; @Enumerated(EnumType.STRING) @Column(nullable=false) private RelationshipType type; @Column(nullable=false) private Instant validFrom; private Instant validUntil; @Column(nullable=false) private boolean active; protected RepresentativeRelationship(){} public RepresentativeRelationship(UUID patientId,UUID userId,RelationshipType type){id=UUID.randomUUID();this.patientId=patientId;this.representativeUserId=userId;this.type=type;validFrom=Instant.now();active=true;} public void revoke(){active=false;validUntil=Instant.now();} public UUID getId(){return id;} public UUID getPatientId(){return patientId;} public UUID getRepresentativeUserId(){return representativeUserId;} public RelationshipType getType(){return type;} public boolean isActive(){return active;} public Instant getValidFrom(){return validFrom;} public Instant getValidUntil(){return validUntil;} }
